import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';


export type TelecomIconProps = Record<string, any>;

const TelecomIcon: React.FC<TelecomIconProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = true,
  durationInSeconds = 10,
  waveColor = "#38BDF8",
  personColor = "#F8FAFC",
  headsetColor = "#F43F5E",
  waveCount = 90,
  waveSpeed = 0.08,
  waveRadius = 75,
  iconScale = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive sizing (optimized for 9:16 but works dynamically)
  const size = Math.min(width, height) * 0.8 * iconScale;
  const viewBoxSize = 200;
  const center = viewBoxSize / 2;

  // Calculate dynamic line width based on radius and count
  const circumference = 2 * Math.PI * waveRadius;
  const lineWidth = Math.max(1, (circumference / waveCount) * 0.6);

  // Entrance animations
  const iconEntranceScale = spring({
    fps,
    frame: frame - 15, // Delay slightly so waves appear first
    config: { damping: 14, mass: 0.8 },
  });

  // Continuous subtle motion for the person icon
  const breathY = interpolate(Math.sin(frame * 0.05), [-1, 1], [-1.5, 1.5]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div style={{ width: size, height: size, position: "relative" }}>
        <svg
          viewBox={`0 0 ${viewBoxSize} ${viewBoxSize}`}
          style={{ width: "100%", height: "100%", overflow: "visible", transition: "none" }}
        >
          {/* Sound Waves Outline */}
          <g>
            {Array.from({ length: waveCount }).map((_, i) => {
              const normalizedIndex = i / waveCount;
              const angle = normalizedIndex * Math.PI * 2;
              const angleDeg = (normalizedIndex * 360);

              // Staggered entrance spring for each wave
              const entrance = spring({
                fps,
                frame: frame - i * (20 / waveCount),
                config: { damping: 12 },
              });

              // Dynamic wave oscillation physics (Voice Visualizer Effect)
              const timeOffset = frame * waveSpeed;
              
              // Complex sine interference to mimic organic audio frequencies
              const v1 = Math.sin(angle * 3 + timeOffset);
              const v2 = Math.cos(angle * 5 - timeOffset * 1.2);
              const v3 = Math.sin(angle * 2 + timeOffset * 0.8);
              
              // Modulation envelope to create "active" and "quiet" zones around the circle
              const envelope = (Math.sin(angle * 2 - timeOffset * 0.5) + 1) / 2;
              const activeLevel = Math.abs((v1 + v2 + v3) / 3) * envelope;

              const minHeight = 4;
              const maxHeight = 30;
              const targetHeight = minHeight + (maxHeight - minHeight) * activeLevel;
              const finalHeight = targetHeight * Math.max(0, entrance);

              return (
                <rect
                  key={`wave-${i}`}
                  x={-lineWidth / 2}
                  y={-finalHeight / 2}
                  width={lineWidth}
                  height={Math.max(0.1, finalHeight)} // Prevent negative/zero height
                  rx={lineWidth / 2}
                  fill={waveColor}
                  style={{ transition: "none" }}
                  transform={`translate(${center}, ${center}) rotate(${angleDeg}) translate(0, -${waveRadius})`}
                />
              );
            })}
          </g>

          {/* Person with Telecom Headset */}
          <g
            style={{
              transformOrigin: `${center}px ${center}px`,
              transition: "none",
            }}
            transform={`translate(0, ${breathY}) scale(${Math.max(0, iconEntranceScale)})`}
          >
            {/* Person Body */}
            <path
              d="M 60 145 C 60 105, 140 105, 140 145 Z"
              fill={personColor}
              style={{ transition: "none" }}
            />
            
            {/* Person Head */}
            <circle cx="100" cy="80" r="22" fill={personColor} style={{ transition: "none" }} />

            {/* Headset Band */}
            <path
              d="M 75 80 A 25 25 0 0 1 125 80"
              fill="none"
              stroke={headsetColor}
              strokeWidth="6"
              strokeLinecap="round"
              style={{ transition: "none" }}
            />

            {/* Headset Earpieces */}
            <rect x="70" y="72" width="8" height="20" rx="4" fill={headsetColor} style={{ transition: "none" }} />
            <rect x="122" y="72" width="8" height="20" rx="4" fill={headsetColor} style={{ transition: "none" }} />

            {/* Microphone Arm */}
            <path
              d="M 126 88 Q 130 115, 110 115"
              fill="none"
              stroke={headsetColor}
              strokeWidth="4"
              strokeLinecap="round"
              style={{ transition: "none" }}
            />

            {/* Microphone Tip */}
            <circle cx="107" cy="115" r="5" fill={headsetColor} style={{ transition: "none" }} />
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default TelecomIcon;